# Free-text assistance types seen so far -> need type codes. Anything else is kept in notes.
ASSISTANCE_TYPE_TO_NEED = {
    "food": "food",
    "doctor": "medical", "medical": "medical", "medicine": "medical", "nurse": "medical",
    "boat": "rescue", "rescue": "rescue", "swimmer": "rescue",
    "water": "water",
    "shelter": "shelter", "transport": "shelter",
}


def map_assistance_types_to_skills(apps, schema_editor):
    Volunteer = apps.get_model("volunteer_hub", "Volunteer")
    NeedType = apps.get_model("incident_manager", "NeedType")
    needs = {n.code: n for n in NeedType.objects.all()}
    for volunteer in Volunteer.objects.exclude(assistance_type=""):
        value = volunteer.assistance_type.strip()
        code = ASSISTANCE_TYPE_TO_NEED.get(value.lower())
        if code in needs:
            volunteer.skills.add(needs[code])
        elif value:
            note = f"Previous assistance type: {value}"
            volunteer.notes = f"{volunteer.notes}\n{note}" if volunteer.notes else note
            volunteer.save(update_fields=["notes"])


